-- LOT 26: Campus operations + high-security dynamic attendance.
CREATE TABLE IF NOT EXISTS campus_attendance_policies (id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL UNIQUE,qr_ttl_seconds integer NOT NULL CHECK(qr_ttl_seconds BETWEEN 5 AND 60),require_device_binding boolean NOT NULL DEFAULT true,require_location boolean NOT NULL DEFAULT false,location_latitude double precision,location_longitude double precision,radius_meters integer NOT NULL CHECK(radius_meters BETWEEN 10 AND 1000),max_accuracy_meters integer NOT NULL CHECK(max_accuracy_meters BETWEEN 5 AND 500),require_network_proof boolean NOT NULL DEFAULT false,row_version integer NOT NULL CHECK(row_version>0),updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS campus_attendance_sessions (id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL,teaching_session_id varchar(64) NOT NULL UNIQUE,offering_id varchar(64) NOT NULL,state varchar(24) NOT NULL CHECK(state IN ('draft','open','closed','cancelled')),opens_at timestamptz NOT NULL,closes_at timestamptz NOT NULL,qr_epoch integer NOT NULL DEFAULT 0,row_version integer NOT NULL CHECK(row_version>0),created_by varchar(64) NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CHECK(closes_at>opens_at));
CREATE INDEX IF NOT EXISTS ix_attendance_session_institution_state ON campus_attendance_sessions(institution_id,state);
CREATE TABLE IF NOT EXISTS campus_attendance_devices (id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL,student_account_id varchar(64) NOT NULL,device_id varchar(128) NOT NULL,bound_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(institution_id,student_account_id));
CREATE INDEX IF NOT EXISTS ix_attendance_device_fingerprint ON campus_attendance_devices(institution_id,device_id);
CREATE TABLE IF NOT EXISTS campus_attendance_records (id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL,attendance_session_id varchar(64) NOT NULL,student_account_id varchar(64) NOT NULL,status varchar(24) NOT NULL CHECK(status IN ('present','late','absent','justified')),recorded_at timestamptz NOT NULL,method varchar(32) NOT NULL,device_id varchar(128),risk_score integer NOT NULL CHECK(risk_score BETWEEN 0 AND 100),review varchar(24) NOT NULL CHECK(review IN ('clear','needs_review','confirmed','rejected')),evidence varchar(4000) NOT NULL DEFAULT '',row_version integer NOT NULL CHECK(row_version>0),updated_at timestamptz NOT NULL,UNIQUE(attendance_session_id,student_account_id));
CREATE INDEX IF NOT EXISTS ix_attendance_review_queue ON campus_attendance_records(institution_id,review,recorded_at);
CREATE TABLE IF NOT EXISTS campus_announcements (id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL,offering_id varchar(64),title varchar(240) NOT NULL,body varchar(8000) NOT NULL,audience varchar(32) NOT NULL,published_at timestamptz NOT NULL,created_by varchar(64) NOT NULL);
